<script setup lang="ts">import{computed}from'vue';import{useRoute}from'vue-router';import PageHeader from'@/components/PageHeader.vue';import{projects,tasks,taskMessages,statusLabel,libraryFiles}from'@/data/mock';const props=defineProps<{kind:string}>();const route=useRoute();const project=computed(()=>projects.find(x=>x.id===route.params.id)||projects[0]);const task=computed(()=>tasks.find(x=>x.id===route.params.id)||tasks[0])</script><template><section class="flex min-w-0 flex-1 flex-col overflow-hidden"><template v-if="kind==='project'"><PageHeader :title="`${project!.emoji} ${project!.name}`" :description="project!.desc"><UButton icon="i-lucide-plus" label="新建任务"/></PageHeader><div class="grid flex-1 gap-6 overflow-y-auto p-6 lg:grid-cols-[1fr_300px]"><section><h2 class="mb-3 text-sm font-medium">项目任务</h2><div class="flex flex-col gap-2"><RouterLink v-for="x in tasks.filter(t=>t.project===project!.name).length?tasks.filter(t=>t.project===project!.name):tasks.slice(0,2)" :key="x.id" :to="`/task/${x.id}`"><UCard><div class="flex justify-between"><b class="text-sm">{{x.title}}</b><UBadge color="neutral">{{statusLabel[x.status]}}</UBadge></div><p class="mt-2 text-xs text-muted">{{x.summary}}</p></UCard></RouterLink></div></section><aside class="flex flex-col gap-4"><UCard><h3 class="font-medium">成员</h3><div class="mt-3 flex -space-x-2"><UAvatar v-for="i in project!.members" :key="i" :alt="`成员 ${i}`"/></div></UCard><UCard><h3 class="font-medium">项目资料</h3><p v-for="f in libraryFiles.slice(0,3)" :key="f.id" class="mt-3 text-xs">{{f.name}}<span class="block text-muted">{{f.from}} · {{f.size}}</span></p></UCard></aside></div></template><template v-else><header class="flex items-center justify-between border-b border-default px-6 py-4"><div><div class="flex items-center gap-2"><h1 class="font-semibold">{{task!.title}}</h1><UBadge>{{statusLabel[task!.status]}}</UBadge></div><p class="mt-1 text-xs text-muted">{{task!.project}} · {{task!.updatedAt}}</p></div><div><UButton icon="i-lucide-share-2" color="neutral" variant="ghost"/><UButton icon="i-lucide-download" color="neutral" variant="ghost"/></div></header><div class="flex-1 overflow-y-auto p-6"><div class="mx-auto flex max-w-2xl flex-col gap-4"><div v-for="(m,i) in taskMessages" :key="i" :class="m.role==='user'?'flex justify-end':''"><p v-if="m.role==='user'" class="max-w-[85%] whitespace-pre-wrap rounded-2xl bg-inverted px-4 py-3 text-sm text-inverted">{{m.content}}</p><UAlert v-else-if="m.role==='tool'" icon="i-lucide-wrench" :description="m.content" color="neutral" variant="subtle"/><div v-else class="flex gap-3"><span class="flex size-7 shrink-0 items-center justify-center rounded-lg bg-inverted text-xs text-inverted">W</span><p class="whitespace-pre-wrap text-sm leading-6">{{m.content}}</p></div></div></div></div><div class="border-t border-default p-4"><div class="mx-auto flex max-w-2xl gap-2"><UInput class="flex-1" placeholder="继续追问或补充要求…"/><UButton icon="i-lucide-arrow-up"/></div></div></template></section></template>
